            # The pattern cycles through 1-9 diagonally
            neighbors = []
            for di in [-1, 0, 1]:
                for dj in [-1, 0, 1]:
                    if di == 0 and dj == 0:
                        continue
                    ni, nj = i + di, j + dj
                    if 0 <= ni < 23 and 0 <= nj < 23 and output[ni][nj] != 0:
                        neighbors.append(output[ni][nj])

            if neighbors:
                # Mode of neighbors (most common value)
                from collections import Counter
                val = Counter(neighbors).most_common(1)[0][0]
                output[i][j] = val
            else:
